package org.springframework.samples.petclinic.rest.function.owner;

import java.util.HashSet;
import java.util.Set;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where
 * REGION is the region code derived from the postcode and HASH8 is the first 8
 * upper-case hex characters of SHA-256 over (normalizedTelephone + lastName) — see
 * {@link CustomerCodes}. The base identity is a pure function of the owner's own fields.
 *
 * <p>When the computed code collides with an existing owner's {@code customerCode}, a
 * {@code -<n>} suffix is appended with the smallest {@code n} of 2 or more that makes it
 * unique, so distinct owners always end up with distinct customerCodes.
 */
public class AssignCustomerCode {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        Set<String> existing = new HashSet<>();
        for (Owner other : ownerRepository.findAll()) {
            if (other.getCustomerCode() != null) {
                existing.add(other.getCustomerCode());
            }
        }
        String base = CustomerCodes.forOwner(owner);
        String code = base;
        for (int n = 2; existing.contains(code); n++) {
            code = base + "-" + n;
        }
        owner.setCustomerCode(code);
    }
}

